'use client';

import * as React from 'react';

// @interlace/type-answer v1.1.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/type-answer
// What changed since: https://ds.interlace.tools/c/type-answer#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — TypeAnswer
 *
 * A quiz round where people type the answer. Harder than picking, and
 * fairer than it looks: case, accents, punctuation and a slip of a letter in
 * a long word are forgiven, while a different number never is (see
 * `typed-answer-model`). The reveal marks the answer, says in words how you
 * did (and the right spelling when you were close), and shows what the room
 * typed, folded together, so a common wrong answer becomes the talking
 * point.
 *
 * ## Anatomy
 *
 *   TypeAnswer                       (div — data-slot="type-answer", data-state=asking|revealed, data-outcome)
 *     ├─ div                         (data-slot="type-answer-header": meta, clock and "Stop the clock")
 *     ├─ p                           (data-slot="type-answer-prompt", labels the field)
 *     ├─ form                        (data-slot="type-answer-form": Input + Answer; Enter sends)
 *     ├─ p tabIndex=-1 aria-live     (data-slot="type-answer-result")
 *     ├─ TallyBars                   (data-slot="type-answer-spread": what the room typed, optional)
 *     └─ div                         (data-slot="type-answer-explanation": opens on reveal)
 *
 * ## The clock
 *
 * As in `QuizQuestion`: `timeLimit` starts a TimerRing when the round is on
 * screen; running out sends whatever is typed so far (an empty field is no
 * answer). "Stop the clock" turns it off (WCAG 2.2.1) and scores without
 * the speed share. Typing takes longer than tapping: give it more seconds.
 *
 * ## Motion
 *
 * On the reveal the field settles with a small lift when right and a short
 * sideways shake when wrong (250ms, transform), and the room's bars grow.
 * Under reduced motion all of it is in its end state.
 *
 * ## MIN_VIEWPORT — 320
 *
 * | Rule | Concept                   | Where in this file                                    |
 * | ---- | ------------------------- | ----------------------------------------------------- |
 * | R4   | Extends native el         | `div` props                                           |
 * | R6   | data-slot per part        | type-answer / -header / -prompt / -form / -field / -send / -result / -spread / -explanation |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                     |
 * | R9   | Controlled + uncontrolled | `result` / `defaultResult` / `onAnswer`               |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const                  |
 * | R26  | A11y                      | labelled field; outcome in words; result focused; a close answer spelled out |
 */

import { cn } from '@/lib/utils';
import { motionEase } from '@/lib/motion-token';
import { useReducedMotion } from '@/hooks/use-reduced-motion';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { QuizScoreOptions } from '@/components/ui/games/quiz-model';
import { TallyBars, type TallyBarsLabels, type TallyMark } from '@/components/ui/games/tally-bars';
import { tally } from '@/components/ui/games/tally-model';
import { TimerRing, type TimerRingLabels } from '@/components/ui/games/timer-ring';
import { groupTyped, normalizeAnswer, scoreTyped, type TypedResult, type TypedRules } from '@/components/ui/games/typed-answer-model';

export const MIN_VIEWPORT = 320 as const;

interface TypeAnswerLabels {
  /** @default 'Answer' */
  send?: string;
  /** The field's placeholder. @default 'Type your answer' */
  placeholder?: string;
  /** The result sentence. `answer` is the first accepted answer. */
  result?: (r: { outcome: 'exact' | 'close' | 'wrong' | 'timeout'; points: number; answer: string }) => string;
  /** @default 'Stop the clock' */
  stopClock?: string;
  /** @default 'Clock stopped' */
  clockStopped?: string;
  /** Names the room's answers. @default 'What the room typed' */
  spread?: string;
  /** The row that folds the rest together. @default 'Something else' */
  other?: string;
  timer?: TimerRingLabels;
  tally?: TallyBarsLabels;
}

type TypeAnswerProps = Omit<React.ComponentProps<'div'>, 'children' | 'onChange'> &
  TypedRules & {
    question: React.ReactNode;
    /** Every answer that counts, the main one first. Keep them off the client until the reveal if the game is competitive. */
    accepted: readonly string[];
    /** Seconds to answer. Leave out for no clock. */
    timeLimit?: number;
    result?: TypedResult | null;
    defaultResult?: TypedResult | null;
    /** Called once, when the player sends or time runs out. */
    onAnswer?: (result: TypedResult) => void;
    /** What everyone else typed, shown after the reveal. */
    room?: readonly string[];
    /** `room` already holds this player's answer. @default false */
    roomIncludesAnswer?: boolean;
    /** Rows in the room's answers before the rest fold into one. @default 5 */
    spreadRows?: number;
    /** @default 60 */
    maxLength?: number;
    meta?: React.ReactNode;
    explanation?: React.ReactNode;
    score?: QuizScoreOptions;
    locale?: string;
    labels?: TypeAnswerLabels;
  };

const RESULT: NonNullable<TypeAnswerLabels['result']> = ({ outcome, points, answer }) =>
  outcome === 'exact'
    ? `Right. +${points} points.`
    : outcome === 'close'
      ? `Right, it is spelled ${answer}. +${points} points.`
      : outcome === 'timeout'
        ? `Time's up. The answer is ${answer}.`
        : `Not this time. The answer is ${answer}.`;

function TypeAnswer({
  question,
  accepted,
  timeLimit,
  result: resultProp,
  defaultResult = null,
  onAnswer,
  room,
  roomIncludesAnswer = false,
  spreadRows = 5,
  maxLength = 60,
  meta,
  explanation,
  score,
  tolerance,
  ignore,
  locale,
  labels,
  className,
  ...props
}: TypeAnswerProps) {
  const [uncontrolled, setUncontrolled] = React.useState<TypedResult | null>(defaultResult);
  const result = resultProp === undefined ? uncontrolled : resultProp;
  const revealed = result !== null && result !== undefined;
  const reduced = useReducedMotion();
  const timed = typeof timeLimit === 'number' && timeLimit > 0;
  const [text, setText] = React.useState('');
  const [deadline, setDeadline] = React.useState<number | null>(null);
  const [stopped, setStopped] = React.useState(false);
  const startRef = React.useRef<number | null>(null);
  const sent = React.useRef(revealed);
  const animate = React.useRef(false);
  const promptId = React.useId();
  const explanationId = React.useId();
  const fieldRef = React.useRef<HTMLInputElement>(null);
  const resultRef = React.useRef<HTMLParagraphElement>(null);
  const rules = { tolerance, ignore };

  React.useEffect(() => {
    if (!timed || revealed) return;
    const start = Date.now();
    startRef.current = start;
    setDeadline(start + (timeLimit as number) * 1000);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [timed, timeLimit]);

  React.useEffect(() => {
    if (!revealed) sent.current = false;
  }, [revealed]);

  const answer = (typed: string | null) => {
    if (revealed || sent.current) return;
    sent.current = true;
    animate.current = true;
    const limitMs = timed ? (timeLimit as number) * 1000 : undefined;
    const elapsedMs = timed && !stopped && startRef.current !== null ? Date.now() - startRef.current : undefined;
    const scored = scoreTyped({ text: typed, limitMs, elapsedMs }, accepted, { ...score, ...rules });
    setDeadline(null);
    if (resultProp === undefined) setUncontrolled(scored);
    onAnswer?.(scored);
  };

  React.useEffect(() => {
    if (!revealed || !animate.current) return;
    animate.current = false;
    // Take focus from the field (or from nowhere, on a timeout); never from elsewhere on the page.
    const active = document.activeElement;
    if (!active || active === document.body || fieldRef.current?.form?.contains(active)) resultRef.current?.focus();
    const field = fieldRef.current;
    if (reduced || !field || typeof field.animate !== 'function') return;
    const timing = { duration: 250, easing: motionEase(field, 'move') };
    if (result.outcome === 'correct') {
      field.animate([{ transform: 'none' }, { transform: 'translateY(-3px)' }, { transform: 'none' }], timing);
    } else if (result.outcome === 'wrong') {
      field.animate(
        [
          { transform: 'none' },
          { transform: 'translateX(-4px)' },
          { transform: 'translateX(4px)' },
          { transform: 'translateX(-2px)' },
          { transform: 'none' },
        ],
        timing,
      );
    }
    // Once, on the reveal.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [revealed]);

  const main = accepted[0] ?? '';
  const mark: TallyMark | undefined = !revealed ? undefined : result.outcome === 'correct' ? 'correct' : 'wrong';
  const shownText = revealed ? (result.text ?? '') : text;

  const spread = React.useMemo(() => {
    if (!revealed || !room) return null;
    const own = result.text && normalizeAnswer(result.text, ignore) ? result.text : null;
    const all = own && !roomIncludesAnswer ? [...room, own] : [...room];
    const groups = groupTyped(all, accepted, rules);
    if (groups.length === 0) return null;
    const keep = Math.max(1, spreadRows);
    // The right answer always has a row, even when few typed it.
    const right = groups.find((g) => g.correct);
    let top = groups.slice(0, keep);
    if (right && !top.includes(right)) top = [...top.slice(0, keep - 1), right];
    const rest = groups.filter((g) => !top.includes(g)).reduce((n, g) => n + g.count, 0);
    const ids = top.map((_, i) => `g${i}`).concat(rest > 0 ? ['other'] : []);
    const counts: Record<string, number> = Object.fromEntries(top.map((g, i) => [`g${i}`, g.count]));
    if (rest > 0) counts.other = rest;
    const mine =
      own === null
        ? null
        : result.outcome === 'correct'
          ? `g${top.indexOf(right as (typeof groups)[number])}`
          : (() => {
              const i = top.findIndex(
                (g) => !g.correct && normalizeAnswer(g.text, ignore) === normalizeAnswer(own, ignore),
              );
              return i >= 0 ? `g${i}` : rest > 0 ? 'other' : null;
            })();
    const names: Record<string, React.ReactNode> = Object.fromEntries(top.map((g, i) => [`g${i}`, g.text]));
    names.other = labels?.other ?? 'Something else';
    const marks: Record<string, TallyMark> = {};
    top.forEach((g, i) => {
      if (g.correct) marks[`g${i}`] = 'correct';
    });
    if (mine && !marks[mine]) marks[mine] = 'wrong';
    return { rows: tally(ids, counts, { vote: mine, countsIncludeVote: true }).rows, names, marks };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [revealed, result, room, roomIncludesAnswer, accepted, spreadRows, tolerance, ignore, labels?.other]);

  return (
    <div
      data-slot="type-answer"
      data-state={revealed ? 'revealed' : 'asking'}
      data-outcome={revealed ? result.outcome : undefined}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('grid gap-5', className)}
      {...props}
    >
      {meta || timed ? (
        <div data-slot="type-answer-header" className="flex min-h-10 flex-wrap items-center justify-between gap-3">
          <div className="text-muted-foreground text-sm font-medium">{meta}</div>
          {timed && !revealed ? (
            <div className="flex items-center gap-2">
              {stopped ? (
                <span className="text-muted-foreground text-sm">{labels?.clockStopped ?? 'Clock stopped'}</span>
              ) : (
                <>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => {
                      setStopped(true);
                      setDeadline(null);
                    }}
                  >
                    {labels?.stopClock ?? 'Stop the clock'}
                  </Button>
                  <TimerRing
                    seconds={timeLimit as number}
                    deadline={deadline}
                    onExpire={() => answer(text.trim() ? text : null)}
                    labels={labels?.timer}
                  />
                </>
              )}
            </div>
          ) : null}
        </div>
      ) : null}

      <p id={promptId} data-slot="type-answer-prompt" className="font-heading text-xl font-semibold text-balance">
        {question}
      </p>

      <form
        data-slot="type-answer-form"
        className="flex flex-wrap gap-2"
        onSubmit={(e) => {
          e.preventDefault();
          if (text.trim()) answer(text);
          else fieldRef.current?.focus();
        }}
      >
        <Input
          ref={fieldRef}
          data-slot="type-answer-field"
          aria-labelledby={promptId}
          value={shownText}
          onChange={(e) => setText(e.target.value)}
          readOnly={revealed}
          maxLength={maxLength}
          autoComplete="off"
          autoCapitalize="off"
          autoCorrect="off"
          spellCheck={false}
          enterKeyHint="send"
          placeholder={revealed ? undefined : (labels?.placeholder ?? 'Type your answer')}
          className={cn(
            'min-w-0 flex-1 basis-48',
            mark === 'correct' && 'border-success bg-success/10',
            mark === 'wrong' && 'border-destructive bg-destructive/10',
          )}
        />
        {revealed ? null : (
          <Button data-slot="type-answer-send" type="submit">
            {labels?.send ?? 'Answer'}
          </Button>
        )}
      </form>

      <p
        ref={resultRef}
        tabIndex={-1}
        data-slot="type-answer-result"
        aria-live="polite"
        aria-describedby={revealed && explanation ? explanationId : undefined}
        className={cn(
          'focus-visible:outline-ring rounded-sm text-base font-semibold outline-offset-4 empty:hidden focus-visible:outline-2',
          revealed && result.outcome === 'correct' ? 'text-success' : 'text-foreground',
        )}
      >
        {revealed
          ? (labels?.result ?? RESULT)({
              outcome:
                result.outcome === 'timeout'
                  ? 'timeout'
                  : result.outcome === 'wrong'
                    ? 'wrong'
                    : result.match.outcome === 'close'
                      ? 'close'
                      : 'exact',
              points: result.points,
              answer: result.match.matched ?? main,
            })
          : ''}
      </p>

      {spread ? (
        <section
          data-slot="type-answer-spread"
          aria-label={labels?.spread ?? 'What the room typed'}
          className="grid gap-2"
        >
          <p className="text-muted-foreground text-xs font-semibold tracking-wide uppercase">
            {labels?.spread ?? 'What the room typed'}
          </p>
          <TallyBars
            rows={spread.rows}
            optionLabels={spread.names}
            marks={spread.marks}
            locale={locale}
            labels={labels?.tally}
          />
        </section>
      ) : null}

      {explanation ? (
        <div
          data-slot="type-answer-explanation"
          className={cn(
            'grid',
            'motion-safe:transition-[grid-template-rows,opacity] motion-safe:duration-(--duration-medium) motion-safe:ease-enter',
            revealed ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0',
          )}
          inert={revealed ? undefined : true}
        >
          <div
            id={explanationId}
            className="text-muted-foreground -m-1 min-h-0 overflow-hidden p-1 text-sm leading-relaxed"
          >
            {explanation}
          </div>
        </div>
      ) : null}
    </div>
  );
}
TypeAnswer.displayName = 'TypeAnswer';

export { TypeAnswer };
export type { TypeAnswerProps, TypeAnswerLabels };

export type QuizOutcome = 'correct' | 'wrong' | 'timeout';

export interface QuizScoreOptions {
  /** Points for a right answer given at once. @default 1000 */
  maxPoints?: number;
  /** Share of the points that depends on speed, 0–1. @default 0.5 */
  speedShare?: number;
}

export interface QuizAnswerInput {
  /** The chosen option's id; null when time ran out first. */
  choice: string | null;
  /** Milliseconds from the start to the answer. Leave out when the clock was stopped. */
  elapsedMs?: number;
  /** The question's time limit in milliseconds. Leave out for an untimed question. */
  limitMs?: number;
}

export interface QuizResult {
  choice: string | null;
  correct: string;
  outcome: QuizOutcome;
  points: number;
  /** Whether the answer raced a running clock (the speed share was in play). */
  timed: boolean;
  elapsedMs?: number;
}

const clamp01 = (n: number) => Math.min(1, Math.max(0, n));

/** Score one answer against the right option's id. */
export function scoreAnswer(input: QuizAnswerInput, correct: string, options: QuizScoreOptions = {}): QuizResult {
  const { maxPoints = 1000 } = options;
  const speedShare = clamp01(options.speedShare ?? 0.5);
  const { choice, elapsedMs, limitMs } = input;
  const limited = typeof limitMs === 'number' && limitMs > 0;
  const timed = limited && typeof elapsedMs === 'number' && Number.isFinite(elapsedMs);
  const outcome: QuizOutcome = choice === null ? 'timeout' : choice === correct ? 'correct' : 'wrong';
  let points = 0;
  if (outcome === 'correct') {
    const base = limited ? maxPoints * (1 - speedShare) : maxPoints;
    const speed = timed ? maxPoints * speedShare * (1 - clamp01((elapsedMs as number) / (limitMs as number))) : 0;
    points = Math.round(base + speed);
  }
  return { choice, correct, outcome, points, timed, ...(timed ? { elapsedMs } : {}) };
}

/**
 * @interlace/ui — games/quiz-model
 *
 * Scoring for a multiple-choice question, with an optional clock. Pure, so a
 * server can score the same answer and a share card can show right or wrong
 * without the answer itself.
 *
 * ## Points
 *
 * A right answer is worth `maxPoints`. When the question was timed, part of
 * that (`speedShare`, half by default) depends on speed: answering at once
 * keeps all of it, answering as the clock runs out keeps none of it. A wrong
 * answer, or no answer before time ran out, is worth 0.
 *
 * A question with no time limit is worth the full `maxPoints`. When a timed
 * question's clock was stopped (a player can always stop it; see QuizQuestion)
 * the answer keeps the part that does not depend on speed, so stopping the
 * clock is always available and never pays more than racing it.
 */

export interface TallyRow {
  id: string;
  count: number;
  /** count / total, 0–1. 0 when nobody has voted. */
  share: number;
  /** Whole percent; the rows sum to 100 when total > 0. */
  percent: number;
  /** The viewer's own choice. */
  mine: boolean;
  /** Has the highest count (ties all lead). False when nobody has voted. */
  leading: boolean;
}

export interface TallyOptions {
  /** The viewer's choice, if any. */
  vote?: string | null;
  /** The counts already include the viewer's vote. @default false */
  countsIncludeVote?: boolean;
}

export interface Tally {
  rows: TallyRow[];
  total: number;
}

/** Whole percents that sum to 100 (largest remainder). All 0 when the total is 0. */
export function wholePercents(counts: readonly number[]): number[] {
  const total = counts.reduce((a, b) => a + b, 0);
  if (!(total > 0)) return counts.map(() => 0);
  const exact = counts.map((c) => (c / total) * 100);
  const out = exact.map(Math.floor);
  let left = 100 - out.reduce((a, b) => a + b, 0);
  const order = exact
    .map((e, i) => ({ i, rest: e - Math.floor(e) }))
    // Biggest remainder first; on a tie the earlier option wins, so the result is stable.
    .sort((a, b) => b.rest - a.rest || a.i - b.i);
  for (const { i } of order) {
    if (left <= 0) break;
    out[i] = (out[i] as number) + 1;
    left -= 1;
  }
  return out;
}

/** The rows for `ids`, in that order. Unknown ids count 0; negative or non-finite counts count 0. */
export function tally(
  ids: readonly string[],
  counts: Readonly<Record<string, number>> = {},
  options: TallyOptions = {},
): Tally {
  const { vote = null, countsIncludeVote = false } = options;
  const raw = ids.map((id) => {
    const n = counts[id];
    const base = typeof n === 'number' && Number.isFinite(n) && n > 0 ? Math.floor(n) : 0;
    return id === vote && !countsIncludeVote ? base + 1 : base;
  });
  const total = raw.reduce((a, b) => a + b, 0);
  const percents = wholePercents(raw);
  const top = Math.max(0, ...raw);
  return {
    total,
    rows: ids.map((id, i) => ({
      id,
      count: raw[i] as number,
      share: total > 0 ? (raw[i] as number) / total : 0,
      percent: percents[i] as number,
      mine: vote !== null && id === vote,
      leading: top > 0 && raw[i] === top,
    })),
  };
}

/**
 * @interlace/ui — games/tally-model
 *
 * Counts per option turned into shares a reader can trust: whole percents
 * that add up to exactly 100, the viewer's own choice included once, and the
 * leading option named. Pure, so a server can return the same numbers the
 * client draws, and a poll and a quiz share one rule.
 *
 * ## Percents that add up
 *
 * Rounding each share on its own can give 33 + 33 + 33 = 99. The largest
 * remainder method hands the missing points to the options that lost the
 * most to rounding, so the column always sums to 100 (or to 0 when nobody
 * has voted).
 *
 * ## The viewer's vote
 *
 * A poll usually knows the tally from the server and the viewer's choice
 * from the tap that just happened. Pass the server counts with
 * `countsIncludeVote: false` (the default) and the viewer's vote is added
 * once, so the bars move the moment they tap. When the server's counts
 * already hold it (a reload), pass `countsIncludeVote: true`.
 */

import { scoreAnswer, type QuizResult, type QuizScoreOptions } from '@/components/ui/games/quiz-model';

/**
 * @interlace/ui — typed-answer-model
 *
 * A quiz round where people type the answer instead of picking it. The
 * hard part is fairness: "Tel-Aviv", "tel aviv" and "Tel Aviv." are the
 * same answer, and a slip of one letter in a long word should still count,
 * while a different number never does ("1948" is not "1949").
 *
 * `normalizeAnswer` folds case, accents and punctuation and collapses
 * spaces. `matchAnswer` compares against every accepted answer: an exact
 * match after folding, or one within a small number of edits that grows
 * with the answer's length (none up to 4 letters, 1 up to 8, then 2).
 * Answers with digits must match exactly. `scoreTyped` scores with the same
 * clock rules as a multiple-choice question (`scoreAnswer`), so the two
 * kinds of round can share a leaderboard. `groupTyped` counts what the room
 * typed, folded together, for the reveal.
 */

export type TypedOutcome = 'exact' | 'close' | 'wrong' | 'empty';

export interface TypedMatch {
  outcome: TypedOutcome;
  /** The accepted answer it matched, as written, or null. */
  matched: string | null;
  /** Edits from the nearest accepted answer, after folding. */
  distance: number;
}

export interface TypedRules {
  /** 'exact' turns typo tolerance off. @default 'close' */
  tolerance?: 'exact' | 'close';
  /** Words to ignore anywhere, e.g. ['the', 'a'] for English. @default [] */
  ignore?: readonly string[];
}

/** Folds case, accents and punctuation; keeps letters, digits, and a point or comma between digits. */
export function normalizeAnswer(text: string, ignore: readonly string[] = []): string {
  const folded = text
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .toLocaleLowerCase()
    .replace(/(?<=\d)[.,](?=\d)/g, '\uE000')
    .replace(/[\p{P}\p{S}]/gu, ' ')
    .replace(/\uE000/g, '.');
  const skip = new Set(ignore.map((w) => normalizeAnswer(w)));
  return folded
    .split(/\s+/)
    .filter((w) => w && !skip.has(w))
    .join(' ');
}

/** Edits (insert, delete, change, swap two neighbours) between two strings, stopping past `max`. */
export function editDistance(a: string, b: string, max = Infinity): number {
  const s = [...a];
  const t = [...b];
  if (Math.abs(s.length - t.length) > max) return max + 1;
  let prev2: number[] = [];
  let prev = Array.from({ length: t.length + 1 }, (_, j) => j);
  for (let i = 1; i <= s.length; i++) {
    const row = [i];
    let best = i;
    for (let j = 1; j <= t.length; j++) {
      const cost = s[i - 1] === t[j - 1] ? 0 : 1;
      let d = Math.min((prev[j] as number) + 1, (row[j - 1] as number) + 1, (prev[j - 1] as number) + cost);
      if (i > 1 && j > 1 && s[i - 1] === t[j - 2] && s[i - 2] === t[j - 1]) {
        d = Math.min(d, (prev2[j - 2] as number) + 1);
      }
      row[j] = d;
      best = Math.min(best, d);
    }
    if (best > max) return max + 1;
    prev2 = prev;
    prev = row;
  }
  return prev[t.length] as number;
}

/** Edits allowed for an accepted answer of this folded length. */
export function allowedEdits(folded: string): number {
  if (/\d/.test(folded)) return 0;
  const n = [...folded.replace(/\s/g, '')].length;
  return n <= 4 ? 0 : n <= 8 ? 1 : 2;
}

export function matchAnswer(text: string, accepted: readonly string[], rules: TypedRules = {}): TypedMatch {
  const { tolerance = 'close', ignore = [] } = rules;
  const typed = normalizeAnswer(text, ignore);
  if (!typed) return { outcome: 'empty', matched: null, distance: Infinity };
  let best: TypedMatch = { outcome: 'wrong', matched: null, distance: Infinity };
  for (const answer of accepted) {
    const target = normalizeAnswer(answer, ignore);
    if (!target) continue;
    const limit = tolerance === 'exact' ? 0 : allowedEdits(target);
    const d = editDistance(typed, target, Math.max(limit, 2));
    if (d === 0) return { outcome: 'exact', matched: answer, distance: 0 };
    if (d <= limit && d < best.distance) best = { outcome: 'close', matched: answer, distance: d };
    else if (best.outcome === 'wrong' && d < best.distance) best = { ...best, distance: d };
  }
  return best;
}

export interface TypedResult extends QuizResult {
  /** What was typed; null when time ran out first. */
  text: string | null;
  match: TypedMatch;
}

/** Scores a typed answer with the quiz clock rules. An empty answer counts as no answer. */
export function scoreTyped(
  input: { text: string | null; elapsedMs?: number; limitMs?: number },
  accepted: readonly string[],
  options: QuizScoreOptions & TypedRules = {},
): TypedResult {
  const match: TypedMatch =
    input.text === null
      ? { outcome: 'empty', matched: null, distance: Infinity }
      : matchAnswer(input.text, accepted, options);
  const choice = match.outcome === 'empty' ? null : match.outcome === 'wrong' ? 'wrong' : 'right';
  const scored = scoreAnswer({ choice, elapsedMs: input.elapsedMs, limitMs: input.limitMs }, 'right', options);
  return { ...scored, text: input.text, match };
}

export interface TypedGroup {
  /** The first way it was written. */
  text: string;
  count: number;
  correct: boolean;
}

/** What the room typed, folded together, most common first; right answers fold into one row. */
export function groupTyped(
  texts: readonly string[],
  accepted: readonly string[],
  rules: TypedRules = {},
): TypedGroup[] {
  const groups = new Map<string, TypedGroup & { first: number }>();
  texts.forEach((text, i) => {
    if (typeof text !== 'string') return;
    const m = matchAnswer(text, accepted, rules);
    if (m.outcome === 'empty') return;
    const right = m.outcome !== 'wrong';
    // A right answer matched something, so there is a first accepted answer to name the row.
    const main = accepted[0] as string;
    const key = right ? `\uE000${main}` : normalizeAnswer(text, rules.ignore);
    const g = groups.get(key);
    if (g) g.count += 1;
    else groups.set(key, { text: right ? main : text.trim(), count: 1, correct: right, first: i });
  });
  return [...groups.values()]
    .sort((a, b) => b.count - a.count || a.first - b.first)
    .map(({ text, count, correct }) => ({ text, count, correct }));
}
